// Filtro consolidado: pausa manual + eco bot + horário comercial opcional
const vars = $('Variáveis').first().json;
const pausaData = $input.first().json;

// 1. Mensagem enviada por nós (eco bot)
if (vars.fromMe === true) {
  // Marca pausa manual (intervenção humana) — TTL 30 min
  return [{ json: { ...vars, action: 'PAUSE_MANUAL', reason: 'fromMe' } }];
}

// 2. IA pausada por intervenção manual
if (pausaData && pausaData.propertyName) {
  return [{ json: { ...vars, action: 'STOP', reason: 'ia_pausada' } }];
}

// 3. Continuar fluxo normal
return [{ json: { ...vars, action: 'CONTINUE' } }];

// Debounce inteligente: só a última execução agrupa e responde
const myTs = parseInt($('Redis: Push Buffer').first().json.timestamp || $now.toMillis());
const buffer = $input.first().json.buffer || [];

if (!Array.isArray(buffer) || buffer.length === 0) {
  return [{ json: { skip: true, reason: 'empty_buffer' } }];
}

const parsed = buffer.map(b => {
  try { return typeof b === 'string' ? JSON.parse(b) : b; } catch { return null; }
}).filter(Boolean);

if (parsed.length === 0) {
  return [{ json: { skip: true, reason: 'parse_failed' } }];
}

// Sou eu a última? Pego a mensagem mais nova do buffer.
const latest = parsed.reduce((acc, m) => (m.ts > acc.ts ? m : acc), parsed[0]);

// Comparo timestamp do meu push com o mais recente. Tolerância 500ms.
const myPushTs = parseInt($now.toMillis()) - 6500; // wait de 6s + folga
const isLatest = Math.abs(latest.ts - myPushTs) < 6500 || parsed.length === 1;

// Sempre processamos se for único na fila; senão só a execução mais recente
const allRecent = parsed.every(m => Math.abs(m.ts - latest.ts) < 7000);

const listaMensagens = parsed.map(m => m.msg).join('\n').trim();

return [{
  json: {
    skip: false,
    listaMensagens,
    countMsgs: parsed.length,
    tipos: [...new Set(parsed.map(m => m.tipo))],
    mobile: $('Variáveis').first().json.mobile,
    pushName: $('Variáveis').first().json.pushName,
    remoteJid: $('Variáveis').first().json.remoteJid
  }
}];

// Resolver sessionId + perfil
const vars = $('Variáveis').first().json;
const consolidado = $('Consolidar Buffer').first().json;
const cliente = $input.first().json;

const isNew = !cliente || !cliente.telefone;

let sessionId;
if (isNew) {
  // Gerar novo session ID
  sessionId = 'grdmad:' + vars.mobile + ':' + Date.now();
} else {
  sessionId = cliente.sessionid || ('grdmad:' + vars.mobile);
}

return [{
  json: {
    isNewCliente: isNew,
    sessionId,
    sessionKey: sessionId,
    mobile: vars.mobile,
    pushName: vars.pushName || cliente?.push_name || '',
    nome: cliente?.nome || vars.pushName || '',
    email: cliente?.email || '',
    empresa: cliente?.empresa || '',
    cidade: cliente?.cidade || '',
    status_atendimento: cliente?.status_atendimento || 'novo',
    estado_funil: cliente?.estado_funil || 'onboarding',
    perfil: cliente?.perfil || null,
    listaMensagens: consolidado.listaMensagens,
    tipos: consolidado.tipos,
    countMsgs: consolidado.countMsgs,
    remoteJid: vars.remoteJid,
    perfil_resumo: cliente?.perfil_resumo || '',
    qtd_interacoes: (cliente?.qtd_interacoes || 0) + 1
  }
}];

