  try {
    const sessao = $('Resolver Sessão').first().json;
    lastClientMsg = (sessao.ultima_mensagem_cliente || sessao.listaMensagens || '').toString();
  } catch (e) {}

  // Pega só a ÚLTIMA mensagem (última linha) se vier histórico
  const linhas = lastClientMsg.split(/\n+/).map(s => s.trim()).filter(Boolean);
  const ultimaLinha = linhas.length > 0 ? linhas[linhas.length - 1] : '';

  // Intenção REAL de cancelar: verbo de comando do cliente
  const CANCEL_INTENT_CLIENT = /\b(quero\s+(cancel|desmarc)|cancel(ar|a|e)?\b|desmarc(ar|a|e)?\b|nao\s+(vou|posso)\s+(mais\s+)?(comparec|particip|ir))/i;
  // Anti-padrão: cliente reclamando que NÃO cancelou (mantém DB intacto)
  const COMPLAINT_NEGATIVE = /\b(n[aã]o\s+(canc|desmarc|remov)|esqueceu\s+de\s+canc|nao\s+foi\s+canc)/i;

  const clientWantsCancel = CANCEL_INTENT_CLIENT.test(ultimaLinha) && !COMPLAINT_NEGATIVE.test(ultimaLinha);

  validation.last_client_msg = ultimaLinha.slice(0, 200);
  validation.client_wants_cancel = clientWantsCancel;

  if (clientWantsCancel && dbReunion && mobile) {
    validation.cancelamento_estrutural = true;
    validation.cancel_payload = { telefone: mobile };
  } else {
    validation.cancelamento_estrutural = false;
    validation.cancel_payload = null;
    // Anotar motivo de não disparar
    if (!clientWantsCancel) validation.cancel_skip_reason = 'NO_CLIENT_INTENT';
    else if (!dbReunion) validation.cancel_skip_reason = 'NO_DB_REUNION';
    else if (!mobile) validation.cancel_skip_reason = 'NO_MOBILE';
  }
}
// Senao, aplica a logica de confirmacao
else if (hasConfirmation) {
  if (linkMatch) {
    // v4.55: verifica se nao eh link placeholder do prompt
    if (isFakeMeetLink(linkMatch[0])) {
      finalResponse = FALLBACK_MSG;
      validation.action = 'BLOCKED_FAKE_MEET_LINK';
      validation.fake_link_detected = linkMatch[0];
    } else {
      validation.action = 'OK_HAS_CONFIRMATION_AND_LINK';
    }
  } else if (dbReunion) {
    if (dataMatch) {
      const isoFromResponse = buildIso(dataMatch, yearImplicit);
      const dbIso = dbReunion.data_reuniao;
      const dbMatches = isoFromResponse && dbIso && datesMatchMinute(isoFromResponse, dbIso);
      validation.date_db_match = dbMatches;
      if (dbMatches) {
        validation.action = 'OK_FROM_DB_LOOKUP';
      } else {
        finalResponse = FALLBACK_MSG;
        validation.action = 'BLOCKED_DATE_MISMATCH';
      }
    } else {
      validation.action = 'OK_FROM_DB_LOOKUP_NO_DATE';
    }
  } else {
    finalResponse = FALLBACK_MSG;
    validation.action = 'BLOCKED_NO_LINK_AND_NO_DB';
  }
}

// Backup Insert so quando ha link real (nao roda em cancelamento ou DB-only)
if (!isCancelContext && hasConfirmation && linkMatch && !isFakeMeetLink(linkMatch[0]) && dataMatch && mobile) {
  const iso = buildIso(dataMatch, yearImplicit);
  if (iso) {
    const alreadyInDb = dbReunion && dbReunion.link === linkMatch[0]
                        && datesMatchMinute(iso, dbReunion.data_reuniao);
    if (!alreadyInDb) {
      validation.agendamento_realizado = true;
      validation.insert_payload = {
        telefone: mobile,
        audiencia: inferAudiencia(),
        data_reuniao: iso,
        link_meet: linkMatch[0]
      };
    } else {
      validation.action += '_DB_ALREADY_HAS';
    }
  }
}


// v4.58: anti-duplicacao cross-execução
// Compara finalResponse contra ultima_resposta_ia da sessao.
// Se identico (ignorando whitespace) → produto eh DUPLICADO de execucao anterior → descartar.
try {
  const sessao = $('Resolver Sessão').first().json;
  const ultimaRespostaSessao = (sessao.ultima_resposta_ia || '').trim();
  const novaResposta = (finalResponse || '').trim();

  // Apenas se ambas tem >50 chars (evitar falsos positivos em "ok")
  if (novaResposta.length > 50 && ultimaRespostaSessao.length > 50) {
    // Normaliza whitespace pra comparar
    const norm = s => s.replace(/\s+/g, ' ').trim().toLowerCase();
    if (norm(novaResposta) === norm(ultimaRespostaSessao)) {
      // Duplicada! Substitui por mensagem neutra (ou vazia)
      finalResponse = '';  // empty — humanizador vai pular
      validation.duplicate_of_previous = true;
      validation.action = (validation.action || 'PASS_THROUGH') + '_DEDUPED';
    }
  }
} catch (e) {}

return {
  json: {
    output: finalResponse,
    output_original: agentResponse,
    _validation: validation
  }
};

// Validar Humanizacao - v4.46
// Rede de seguranca contra bug #12709 do n8n (output parser leak)
// + consolidador de bloco de confirmacao quebrado em multiplos segmentos.

const item = $input.first().json;

const PARSER_ERROR_MARKER = 'You must format your output as a JSON value';
const SCHEMA_HINT_MARKER = 'JSON Schema';

// Detecta linha que faz parte do bloco confirmacao (comecam com emojis ou ✅)
const CONFIRM_LINE_RE = /^[✅📅🔗⏱️🕐📆🎯]/;

let messages = null;
let usedFallback = false;
let fallbackReason = null;
let consolidated = false;

const out = item.output;
// v4.58: se output veio vazio (dedup), nao enviar nada
if (!out || (typeof out === 'string' && !out.trim())) {
  return [{
    json: {
      ...item,
      output: { messages: [] },
      _humanizer_validation: {
        skipped_empty: true,
        reason: 'Output vazio (provavelmente deduplicado em cross-execucao)'
      }
    }
  }];
}


if (out && Array.isArray(out.messages) && out.messages.length > 0) {
  const hasError = out.messages.some(m => {
    if (typeof m !== 'string') return true;
    if (m.includes(PARSER_ERROR_MARKER)) return true;
    if (out.messages.length === 1 && m.length > 200 && m.includes(SCHEMA_HINT_MARKER)) return true;
    return false;
  });
  if (!hasError) {
    messages = out.messages.map(m => String(m).trim()).filter(Boolean);
  } else {
    fallbackReason = 'output.messages contem string de erro do parser';
  }
} else if (typeof out === 'string') {
  if (out.includes(PARSER_ERROR_MARKER)) {
    fallbackReason = 'output veio como string com erro do parser';
  } else {
    messages = [out.trim()];
  }
} else {
  fallbackReason = 'output sem messages valido';
}

if (!messages || messages.length === 0) {
  usedFallback = true;
  let original = '';
  try {
    original = $('Preparar Persistência').first().json.sdrOutput || '';
  } catch (e) {
    original = '';
  }
  original = String(original).trim();
  if (!original) {
    original = 'Desculpe, tive um problema agora. Pode repetir, por favor?';
  }
  let segs = original.split(/\n\s*\n+/).map(s => s.trim()).filter(Boolean);
  if (segs.length === 0) segs = [original];
  if (segs.length > 3) {
    segs = [segs[0], segs[1], segs.slice(2).join(' ')];
  }
  messages = segs;
}

// === Deduplicador de messages identicas consecutivas (v4.55) ===
// Sintoma observado: LLM as vezes retorna mesma message 2x seguidas
if (messages.length >= 2) {
  const deduped = [messages[0]];
  for (let i = 1; i < messages.length; i++) {
    const prev = deduped[deduped.length - 1].trim();
    const cur = messages[i].trim();
    if (prev !== cur) deduped.push(messages[i]);
  }
  if (deduped.length !== messages.length) {
    consolidated = true; // sinaliza no _humanizer_validation
  }
  messages = deduped;
}

// === Consolidador de bloco de confirmacao ===
// Se 2+ messages consecutivos sao linhas do bloco confirmacao (comecam com
// ✅📅🔗⏱️), funde tudo numa unica mensagem com \n entre as linhas.
if (messages.length >= 2) {
  const consolidatedMsgs = [];
  let buffer = [];
  let inConfirmBlock = false;

  function flushBuffer() {
    if (buffer.length > 0) {
      if (buffer.length >= 2 && inConfirmBlock) {
        consolidatedMsgs.push(buffer.join('\n'));
        consolidated = true;
      } else {
        // so 1 elemento no buffer ou nao era bloco — manda individualmente
        for (const m of buffer) consolidatedMsgs.push(m);
      }
      buffer = [];
    }
  }

  for (const m of messages) {
    const isConfirmLine = CONFIRM_LINE_RE.test(m);
    if (isConfirmLine) {
      // se buffer ainda esta vazio ou estamos em confirm block, acumula
      if (!inConfirmBlock && buffer.length > 0) {
        // estava em outro contexto — flush antes
        flushBuffer();
      }
      inConfirmBlock = true;
      buffer.push(m);
    } else {
      if (inConfirmBlock) {
        // linha extra logo apos bloco confirmacao — anexa
        // (ex: "Enviei tambem por e-mail... Ate la!")
        buffer.push(m);
        flushBuffer();
        inConfirmBlock = false;
      } else {
        // mensagem normal — flush e manda direto
        flushBuffer();
        consolidatedMsgs.push(m);
      }
    }
  }
  flushBuffer();
  messages = consolidatedMsgs;
}

return [{
  json: {
    ...item,
    output: { messages },
    _humanizer_validation: {
      used_fallback: usedFallback,
      fallback_reason: fallbackReason,
      consolidated_confirm_block: consolidated,
      messages_count: messages.length
    }
  }
}];

// Backup: Preparar Dados Email — extrai dados do Validador + Sessão
// Decide qual tipo de email (confirmacao/reagendamento/cancelamento) baseado no _validation

let validation = {};
let agentResponse = '';
try {
  const valOutput = $('Validador Resposta IA').first().json;
  validation = valOutput._validation || {};
  agentResponse = valOutput.output_original || valOutput.output || '';
} catch (e) {}

let sessao = {};
try {
  sessao = $('Resolver Sessão').first().json;
} catch (e) {}

// Determinar tipo de email
let emailType = 'NONE';
if (validation.cancelamento_estrutural === true) {
  emailType = 'CANCELAMENTO';
} else if (validation.agendamento_realizado === true && validation.is_reschedule_context === true) {
  emailType = 'REAGENDAMENTO';
} else if (validation.agendamento_realizado === true) {
  emailType = 'CONFIRMACAO';
}

// Extrair data e link do payload
let data_reuniao_formatada = '';
let link_meet = '';
const payload = validation.insert_payload || validation.cancel_payload || {};
if (payload.data_reuniao) {
  try {
    const dt = new Date(payload.data_reuniao);
    const pad = n => String(n).padStart(2,'0');
    data_reuniao_formatada = pad(dt.getDate()) + '/' + pad(dt.getMonth()+1) + '/' + dt.getFullYear() + ' ' + pad(dt.getHours()) + ':' + pad(dt.getMinutes());
  } catch (e) {}
}
if (payload.link_meet) link_meet = payload.link_meet;

// Tentar tambem extrair da resposta do agent (date_match e link_in_response)
if (!data_reuniao_formatada && validation.date_match) {
  data_reuniao_formatada = validation.date_match;
}
if (!link_meet && validation.link_in_response) {
  link_meet = validation.link_in_response;
}

// Para CANCELAMENTO sem dados do payload, busca no DB
if (emailType === 'CANCELAMENTO' && !data_reuniao_formatada) {
  try {
    const cancelRows = $('Backup: Cancel Postgres').all();
    if (cancelRows.length > 0 && cancelRows[0].json.data_reuniao) {
      const dt = new Date(cancelRows[0].json.data_reuniao);
      const pad = n => String(n).padStart(2,'0');
      data_reuniao_formatada = pad(dt.getDate()) + '/' + pad(dt.getMonth()+1) + '/' + dt.getFullYear() + ' ' + pad(dt.getHours()) + ':' + pad(dt.getMinutes());
      if (!link_meet) link_meet = cancelRows[0].json.link_meet || '';
    }
  } catch (e) {}
}

// Titulos e corpos por tipo
const TEMPLATES = {
  CONFIRMACAO: {
    titulo: 'Sua reuniao com a GRD MAD esta confirmada',
    corpo: 'Sua reuniao online com nosso especialista esta confirmada. Anote os detalhes abaixo. Se precisar reagendar ou cancelar, eh so me avisar pelo WhatsApp.',
    subject_prefix: 'GRD MAD — Reuniao confirmada em '
  },
  REAGENDAMENTO: {
    titulo: 'Sua reuniao com a GRD MAD foi REAGENDADA',
    corpo: 'Sua reuniao online foi reagendada conforme solicitado. Confira a nova data e o novo link abaixo. Se precisar de outro horario, eh so me avisar pelo WhatsApp.',
    subject_prefix: 'GRD MAD — Reuniao REAGENDADA para '
  },
  CANCELAMENTO: {
    titulo: 'Sua reuniao com a GRD MAD foi CANCELADA',
    corpo: 'Sua reuniao foi cancelada conforme solicitado. Se quiser remarcar mais para frente, eh so me avisar pelo WhatsApp.',
    subject_prefix: 'GRD MAD — Reuniao CANCELADA em '
  }
};

const tpl = TEMPLATES[emailType] || { titulo: '', corpo: '', subject_prefix: '' };

// Preparar dados pra Calendar lookup (delete antigo)
let cal_lookup_time_min = '';
let cal_lookup_time_max = '';
let cal_lookup_query = sessao.mobile || '';

// Pra cancelamento: usa data_reuniao do Cancel Postgres (que retornou)
// Pra reagendamento: pra deletar evento ANTIGO, precisa data_reuniao_antiga
// Backup: Insert Reuniao retorna `data_reuniao` ANTIGA marcada como 'remarcado'
let antigaIso = '';
try {
  if (emailType === 'CANCELAMENTO') {
    const rows = $('Backup: Cancel Postgres').all();
    if (rows.length > 0 && rows[0].json.data_reuniao) {
      antigaIso = rows[0].json.data_reuniao;
    }
  } else if (emailType === 'REAGENDAMENTO') {
    // Backup Insert retorna multiplas linhas: a INSERT new e as UPDATEs antigas (remarcado)
    const insertRows = $('Backup: Insert Reuniao').all();
    for (const r of insertRows) {
      if (r.json.status === 'remarcado' && r.json.data_reuniao) {
        antigaIso = r.json.data_reuniao;
        break;
      }
    }
  }
} catch (e) {}

if (antigaIso) {
  try {
    const dt = new Date(antigaIso);
    const before = new Date(dt.getTime() - 60000);
    const after = new Date(dt.getTime() + 60000);
    cal_lookup_time_min = before.toISOString();
    cal_lookup_time_max = after.toISOString();
  } catch (e) {}
}

const shouldDeleteCal = !!antigaIso && (emailType === 'CANCELAMENTO' || emailType === 'REAGENDAMENTO');

return [{
  json: {
    email_type: emailType,
    should_send_email: emailType !== 'NONE' && !!sessao.email,
    email_cliente: sessao.email || '',
    nome_cliente: sessao.nome || sessao.pushName || 'Cliente',
    audiencia: validation.insert_payload?.audiencia || sessao.perfil || 'B2B',
    data_reuniao_formatada,
    link_meet,
    email_titulo: tpl.titulo,
    email_corpo: tpl.corpo,
    subject: tpl.subject_prefix + data_reuniao_formatada,
    // passthrough do estado anterior pra Preparar Persistencia
    _validation: validation,
    _passthrough: $input.first()?.json || {},
    cal_lookup_time_min,
    cal_lookup_time_max,
    cal_lookup_query,
    should_delete_calendar: shouldDeleteCal
  }
}];
